<?php require 'partials.php';header_html('Standings','standings');?><section class="card"><h1>Group standings</h1><p>Ranking order: winning percentage, tied-team mini-table percentage, tied-team run differential, overall run differential, runs scored.</p></section><div class="grid"><?php foreach(['A','B'] as $group):$rows=standings($group);?><section class="card"><h2>Group <?=$group?></h2><div class="table"><table><thead><tr><th>#</th><th>Team</th><th>G</th><th>W</th><th>L</th><th>RF</th><th>RA</th><th>Diff</th><th>PCT</th><th title="Head-to-head mini-table">TB</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td class="rank"><?=$i+1?></td><td><b><?=h($r['team'])?></b></td><td><?=$r['g']?></td><td><?=$r['w']?></td><td><?=$r['l']?></td><td><?=$r['rf']?></td><td><?=$r['ra']?></td><td><?=($r['diff']>0?'+':'').$r['diff']?></td><td><?=number_format($r['pct'],3)?></td><td><?=number_format($r['tb_pct'],3)?><br><small><?=($r['tb_diff']>0?'+':'').$r['tb_diff']?></small></td></tr><?php endforeach?></tbody></table></div></section><?php endforeach?></div><p class="notice"><b>Tie-break note:</b> the mini-table includes only completed games between tied teams. Official tournament regulations should take precedence if they prescribe a different order.</p><?php footer_html();?>